import asyncio
import hashlib
import hmac
import json
import os
import time
import secrets
from dataclasses import dataclass, field
from typing import Optional, Dict, Set

SECRET_KEY = os.environ.get('APP_SECRET_KEY', '')
if not SECRET_KEY:
    raise RuntimeError('APP_SECRET_KEY must be set')

@dataclass
class Document:
    doc_id: str
    owner_id: str
    content: str
    version: int = 1
    shared_with: Set[str] = field(default_factory=set)
    is_deleted: bool = False

@dataclass
class User:
    user_id: str
    username: str
    role: str = 'user'

class DocumentStore:
    def __init__(self):
        self._documents: Dict[str, Document] = {}
        self._users: Dict[str, User] = {}
        self._lock = asyncio.Lock()

    async def create_document(self, owner_id: str, content: str) -> Document:
        async with self._lock:
            doc_id = secrets.token_hex(16)
            doc = Document(doc_id=doc_id, owner_id=owner_id, content=content)
            self._documents[doc_id] = doc
            return doc

    async def get_document(self, doc_id: str) -> Optional[Document]:
        async with self._lock:
            doc = self._documents.get(doc_id)
            if doc:
                # Return a snapshot to prevent TOCTOU
                return Document(
                    doc_id=doc.doc_id,
                    owner_id=doc.owner_id,
                    content=doc.content,
                    version=doc.version,
                    shared_with=set(doc.shared_with),
                    is_deleted=doc.is_deleted
                )
            return None

    async def update_document(self, doc_id: str, content: str, expected_version: int) -> bool:
        async with self._lock:
            doc = self._documents.get(doc_id)
            if not doc or doc.is_deleted:
                return False
            if doc.version != expected_version:
                return False
            doc.content = content
            doc.version += 1
            return True

    async def delete_document(self, doc_id: str) -> bool:
        async with self._lock:
            doc = self._documents.get(doc_id)
            if not doc:
                return False
            doc.is_deleted = True
            return True

    async def share_document(self, doc_id: str, target_user_id: str) -> bool:
        async with self._lock:
            doc = self._documents.get(doc_id)
            if not doc or doc.is_deleted:
                return False
            doc.shared_with.add(target_user_id)
            return True

    async def unshare_document(self, doc_id: str, target_user_id: str) -> bool:
        async with self._lock:
            doc = self._documents.get(doc_id)
            if not doc:
                return False
            doc.shared_with.discard(target_user_id)
            return True

    async def transfer_ownership_atomic(self, doc_id: str, expected_owner_id: str,
                                         new_owner_id: str) -> bool:
        """Atomically transfer ownership only if current owner matches expected."""
        async with self._lock:
            doc = self._documents.get(doc_id)
            if not doc or doc.is_deleted:
                return False
            if doc.owner_id != expected_owner_id:
                return False
            doc.owner_id = new_owner_id
            return True

    async def register_user(self, username: str, role: str = 'user') -> User:
        async with self._lock:
            user_id = secrets.token_hex(8)
            user = User(user_id=user_id, username=username, role=role)
            self._users[user_id] = user
            return user

    async def get_user(self, user_id: str) -> Optional[User]:
        async with self._lock:
            return self._users.get(user_id)


class AuthorizationEngine:
    """Fine-grained authorization for document operations."""

    def __init__(self, store: DocumentStore):
        self._store = store

    async def check_read_permission(self, user_id: str, doc_id: str) -> bool:
        """Check if user can read the document."""
        doc = await self._store.get_document(doc_id)
        if not doc or doc.is_deleted:
            return False
        user = await self._store.get_user(user_id)
        if not user:
            return False
        if user.role == 'admin':
            return True
        if doc.owner_id == user_id:
            return True
        if user_id in doc.shared_with:
            return True
        return False

    async def check_write_permission(self, user_id: str, doc_id: str) -> bool:
        """Check if user can modify the document."""
        doc = await self._store.get_document(doc_id)
        if not doc or doc.is_deleted:
            return False
        user = await self._store.get_user(user_id)
        if not user:
            return False
        if user.role == 'admin':
            return True
        if doc.owner_id == user_id:
            return True
        return False

