class CollaborationService:
    """Handles collaborative document operations with proper authorization."""

    def __init__(self, store: DocumentStore, auth: AuthorizationEngine):
        self._store = store
        self._auth = auth
        self._operation_log: list = []

    def _sign_token(self, user_id: str, timestamp: float) -> str:
        payload = f"{user_id}:{timestamp}"
        sig = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
        return f"{payload}:{sig}"

    def _verify_token(self, token: str) -> Optional[str]:
        parts = token.split(':')
        if len(parts) != 3:
            return None
        user_id, timestamp_str, signature = parts
        try:
            timestamp = float(timestamp_str)
        except (ValueError, OverflowError):
            return None
        if time.time() - timestamp > 3600:
            return None
        expected_payload = f"{user_id}:{timestamp_str}"
        expected_sig = hmac.new(
            SECRET_KEY.encode(), expected_payload.encode(), hashlib.sha256
        ).hexdigest()
        if not hmac.compare_digest(signature, expected_sig):
            return None
        return user_id

    async def read_document(self, token: str, doc_id: str) -> Optional[Dict]:
        """Read a document with authorization check."""
        user_id = self._verify_token(token)
        if not user_id:
            return None
        if not await self._auth.check_read_permission(user_id, doc_id):
            return None
        doc = await self._store.get_document(doc_id)
        if not doc or doc.is_deleted:
            return None
        return {'doc_id': doc.doc_id, 'content': doc.content, 'version': doc.version}

    async def edit_document(self, token: str, doc_id: str, new_content: str,
                           expected_version: int) -> Dict:
        """Edit a document with optimistic concurrency control."""
        user_id = self._verify_token(token)
        if not user_id:
            return {'success': False, 'error': 'invalid_token'}

        if not isinstance(new_content, str) or len(new_content) > 1_000_000:
            return {'success': False, 'error': 'invalid_content'}
        if not isinstance(expected_version, int) or expected_version < 1:
            return {'success': False, 'error': 'invalid_version'}

        if not await self._auth.check_write_permission(user_id, doc_id):
            return {'success': False, 'error': 'forbidden'}

        success = await self._store.update_document(doc_id, new_content, expected_version)
        if success:
            self._operation_log.append({
                'op': 'edit', 'user': user_id, 'doc': doc_id,
                'time': time.time()
            })
        return {'success': success, 'error': None if success else 'conflict'}

    async def delete_document(self, token: str, doc_id: str) -> Dict:
        """Delete a document with authorization check."""
        user_id = self._verify_token(token)
        if not user_id:
            return {'success': False, 'error': 'invalid_token'}

        if not await self._auth.check_delete_permission(user_id, doc_id):
            return {'success': False, 'error': 'forbidden'}

        success = await self._store.delete_document(doc_id)
        if success:
            self._operation_log.append({
                'op': 'delete', 'user': user_id, 'doc': doc_id,
                'time': time.time()
            })
        return {'success': success}

    async def share_document(self, token: str, doc_id: str,
                            target_user_id: str) -> Dict:
        """Share a document with another user."""
        user_id = self._verify_token(token)
        if not user_id:
            return {'success': False, 'error': 'invalid_token'}

        if not isinstance(target_user_id, str) or len(target_user_id) > 64:
            return {'success': False, 'error': 'invalid_target'}

        if not await self._auth.check_share_permission(user_id, doc_id):
            return {'success': False, 'error': 'forbidden'}

        success = await self._store.share_document(doc_id, target_user_id)
        if success:
            self._operation_log.append({
                'op': 'share', 'user': user_id, 'doc': doc_id,
                'target': target_user_id, 'time': time.time()
            })
        return {'success': success}

    async def transfer_ownership(self, token: str, doc_id: str,
                                 new_owner_id: str) -> Dict:
        """Transfer document ownership to another user.

        This is a sensitive operation that requires careful authorization.
        Only the current owner or an admin can transfer ownership.
        Uses atomic compare-and-swap to prevent TOCTOU races.
        """
        user_id = self._verify_token(token)
        if not user_id:
            return {'success': False, 'error': 'invalid_token'}

        if not isinstance(new_owner_id, str) or len(new_owner_id) > 64:
            return {'success': False, 'error': 'invalid_target'}

        # Verify the new owner exists
        new_owner = await self._store.get_user(new_owner_id)
        if not new_owner:
            return {'success': False, 'error': 'user_not_found'}

        # Check current permission and get current owner atomically
        doc = await self._store.get_document(doc_id)
        if not doc or doc.is_deleted:
            return {'success': False, 'error': 'not_found'}

        user = await self._store.get_user(user_id)
        if not user:
            return {'success': False, 'error': 'forbidden'}

        # Only owner or admin can transfer
        if user.role != 'admin' and doc.owner_id != user_id:
            return {'success': False, 'error': 'forbidden'}

        # Use atomic transfer that verifies owner hasn't changed
        # This prevents TOCTOU: if ownership changed between our check
        # and the actual transfer, this will fail safely
        expected_owner = doc.owner_id
        success = await self._store.transfer_ownership_atomic(
            doc_id, expected_owner, new_owner_id
        )

        if success:
            self._operation_log.append({
                'op': 'transfer', 'user': user_id, 'doc': doc_id,
                'new_owner': new_owner_id, 'time': time.time()
            })
            return {'success': True}
        return {'success': False, 'error': 'conflict'}

    async def batch_operation(self, token: str, operations: list) -> Dict:
        """Execute multiple operations."""
        user_id = self._verify_token(token)
        if not user_id:
            return {'success': False, 'error': 'invalid_token'}

        if not isinstance(operations, list) or len(operations) > 50:
            return {'success': False, 'error': 'invalid_operations'}

        results = []
        for op in operations:
            if not isinstance(op, dict):
                results.append({'success': False, 'error': 'invalid_op'})
                continue

            op_type = op.get('type')
            doc_id = op.get('doc_id')

            if not isinstance(doc_id, str) or len(doc_id) > 64:
                results.append({'success': False, 'error': 'invalid_doc_id'})
                continue

            if op_type == 'read':
                result = await self.read_document(token, doc_id)
                results.append({'success': result is not None, 'data': result})
            elif op_type == 'delete':
                result = await self.delete_document(token, doc_id)
                results.append(result)
            else:
                results.append({'success': False, 'error': 'unknown_op'})

        return {'success': True, 'results': results}
